        let bi = b[i];

        let mut ng: isize = -1;
        let mut ok: isize = n as isize;
        while (ok - ng).abs() > 1 {
            let mid = (ok + ng) / 2;
            if c[mid as usize] > bi {
                ok = mid;
            } else {
                ng = mid;
            }
        }
