use std::cmp;

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let mut count: Vec<usize> = vec![0; n];
    for _ in 0..n {
        let a = sc.read::<usize>() - 1;
        count[a] += 1;
    }

    let mut count_count = vec![0; n + 1];
    for count in count.into_iter() {
        count_count[count] += 1;
    }

    let mut rows = count_count
        .into_iter()
        .enumerate()
        .filter(|&(count, num)| count > 0 && num > 0)
        .collect::<Vec<_>>();
    rows.sort();
    let mut ans = vec![0; n + 1];
    let mut sum = rows.iter().map(|&(count, num)| count * num).sum::<usize>();
    let mut popped = 0;
    for height in (1..(n + 1)).rev() {
        while let Some((max, num)) = rows.pop() {
            if max >= height {
                sum -= max * num;
                popped += num;
            } else {
                rows.push((max, num));
                break;
            }
        }

        let columns = sum / height + popped;
        ans[columns] = cmp::max(ans[columns], height);
    }
    for k in (0..n).rev() {
        ans[k] = cmp::max(ans[k], ans[k + 1]);
    }

    for k in 1..(n + 1) {
        println!("{}", ans[k]);
    }
}

