        if Q[i-1][1] == Q[i][1]:
            uft.unite(Q[i-1][0], Q[i][0])
    R = sorted(P, key=itemgetter(2))
    for i in range(1, N):
        if R[i-1][2] == R[i][2]:
            uft.unite(R[i-1][0], R[i][0])
