fn dfs(r: usize, p: usize, t: &Vec<Vec<usize>>, s: &Vec<char>) -> (usize, usize, usize) {
    let mut n = 0;
    let mut sum = 0;
    let mut m = 0;
    let mut v = s[r].to_digit(10u32).unwrap() as usize;
    for c in t[r].clone() {
        if c == p {
            continue;
        }
        let cs = dfs(c, r, t, s);
        n += cs.0;
        sum += cs.1 + cs.2;
        m = max(m, cs.0 + cs.1 + cs.2);
        v += cs.2;
    }
    if 2 * m >= sum + 2 * n {
        (2 * n + sum - m, 2 * m - sum - 2 * n, v)
    } else {
        (n + sum / 2, sum % 2, v)
    }
