fn solve(src: &str) -> String {
    let mut sc = Scanner::from_str(src);
    use std::fmt::Write;
    let mut buf = String::new();

    let n: usize = sc.read();
    let a: Vec<usize> = sc.vec(n);

    let mut b = vec![0; n];
    for &a in &a {
        b[a-1] += 1;
    }
    let mut c = vec![0; n+1];
    for &b in &b {
        c[b] += 1;
    }
    let mut d = vec![0; n];
    let mut e = 0;
    d[n-1] = n;
    for i in (0..n-1).rev() {
        e += c[i+2];
        d[i] = d[i+1] - e;
    }

    for k in 1..n+1 {
        let ans = bis(0, n+1, |x|
            d[x-1] >= x * k
        );
        writeln!(&mut buf, "{}", ans);
    }

    buf
}
