fn test_solve() {
   assert_eq!(solve("3\n2 1 2\n"), "3\n1\n0\n");
   assert_eq!(solve("5\n1 2 3 4 5\n"), "5\n2\n1\n1\n1\n");
   assert_eq!(solve("4\n1 3 3 3\n"), "4\n1\n0\n0\n");
}
fn bis<P>(t: usize, f: usize, eval: P) -> usize
where
    P: Fn(usize) -> bool,
{
    if t + 1 == f || f + 1 == t {
        return t;
    }
    let m = (t + f) >> 1;
    if eval(m) {
        bis(m, f, eval)
    } else {
        bis(t, m, eval)
    }
}
