fn solve(s: &Vec<char>, ch: char) -> usize {
    if s.iter().all(|c| *c == ch) {
        return 0;
    }
    let mut st = s.clone();
    let mut count = 0;
    let mut flag = true;
    while flag {
        flag = false;
        for i in 0..st.len() - 1 {
            if st[i + 1] == ch {
                st[i] = ch;
            }
            if st[i] != ch {
                flag = true;
            }
        }
        count += 1;
        st.pop();
    }
    return count;
}
