            let tmp_den = beams[i].1;
            if tmp_num * den > tmp_den * num {
                num = tmp_num;
                den = tmp_den;
            }
        }
    }
    num = (n - k) as i64 * den + num;
    den *= n as i64;
    let d = gcd(num, den);
    println!("{} {}", num / d, den / d);
