use std::io::Read;

#[derive(Clone, Copy, Debug, PartialEq, PartialOrd, Eq, Ord)]
enum QueenPos {
    Unfixed,
    Fixed(usize),
}

fn is_placeable(row: usize, col: usize, queens: &[usize]) -> bool {
    (0..row).all(|r| queens[r] != col)
        && (0..row).all(|r| queens[r] != col.wrapping_sub(row - r))
        && (0..row).all(|r| queens[r] != col + (row - r))
}

fn rec(
    row: usize,
    queens: &mut Vec<usize>,
    height: usize,
    width: usize,
    initial_queens: &[QueenPos],
) -> bool {
    if row == height {
        true
    } else {
        match initial_queens[row] {
            QueenPos::Unfixed => (0..width)
                .find(|&col| {
                    is_placeable(row, col, queens) && {
                        queens[row] = col;
                        rec(row + 1, queens, width, height, initial_queens)
                    }
                })
                .map_or(false, |_| true),
            QueenPos::Fixed(col) => {
                is_placeable(row, col, queens) && {
                    queens[row] = col;
                    rec(row + 1, queens, width, height, initial_queens)
                }
            }
        }
    }
}

fn solve(height: usize, width: usize, rc: &[(usize, usize)]) -> Vec<Vec<char>> {
    let mut initial_queens = vec![QueenPos::Unfixed; height];
    for &(r, c) in rc {
        initial_queens[r] = QueenPos::Fixed(c);
    }

    let mut queens = vec![0; height];
    assert!(rec(0, &mut queens, height, width, &initial_queens));
    queens
        .into_iter()
        .map(|col| {
            (0..width)
                .map(|c| if c == col { 'Q' } else { '.' })
                .collect()
        })
        .collect()
}

