    read::<String>().split_whitespace()
        .map(|e| e.parse().ok().unwrap()).collect()
}

struct OrderedString {
    used_chars: usize,
    length: usize,
    string: BTreeMap<usize, usize>,
}

impl OrderedString {
    fn increment(&mut self, length: usize) -> bool {
        if let Some(&v) = self.string.get(&length) {
            if v == self.used_chars - 1 {
                self.string.remove(&length);
                if length == 1 {
                    false
                } else {
                    self.increment(length - 1)
                }
            } else {
                *self.string.get_mut(&length).unwrap() += 1;
                true
            }
        } else if self.used_chars == 1 {
            false
        } else {
            self.string.insert(length, 1);
            true
        }
    }
}

fn is_ok(a: &Vec<usize>, used_chars: usize) -> bool {
    let mut last_string = OrderedString {
        used_chars: used_chars,
        length: a[0],
        string: BTreeMap::new(),
    };
    for i in 1..a.len() {
        if a[i] > a[i - 1] {
            continue;
        }
        if a[i] < a[i - 1] {
            while let Some(&key) = last_string.string.keys().next_back() {
                if key > a[i] {
                    last_string.string.remove(&key);
                } else {
                    break;
                }
            }
            last_string.length = a[i];
        }
        if !last_string.increment(a[i]) {
            return false;
        }
    }
    true
}

fn main() {
    let n: usize = read();
    let a: Vec<usize> = read_vec();

    let mut ng = 0;
    let mut ok = n;
    while ok - ng > 1 {
        let mid = (ok + ng) / 2;
        if is_ok(&a, mid) {
            ok = mid;
        } else {
            ng = mid;
        }
    }
    println!("{}", ok);
}
