use std::str::FromStr;
use std::cmp::min;

fn input<T:FromStr>() -> T {
    let mut line: String = String::new();
    io::stdin().read_line(&mut line);
    line.trim().parse().ok().unwrap()
}

fn input_vec() -> Vec<i32> {
    let mut line: String = String::new();
    io::stdin().read_line(&mut line);
    line.split_whitespace().map(|s| s.parse().unwrap()).collect()
}

fn dp(i: usize, h_vec: &Vec<i32>, cache: &mut Vec<i32>) -> i32 {
    if i == h_vec.len() - 1 {
        return 0;
    }

    if cache[i] != -1 {
        return cache[i];
    }

    let mut res = 0i32;
    if i == h_vec.len() - 2 {
        res = dp(i+1, h_vec, cache) + (h_vec[i+1] - h_vec[i]).abs();
    } else {
        res = min(dp(i+1, h_vec, cache) + (h_vec[i+1] - h_vec[i]).abs(), dp(i+2, h_vec, cache) + (h_vec[i+2] - h_vec[i]).abs());
    }
    cache[i] = res;
    res
}

fn main() {
    let n: i32 = input();
    let h_vec = input_vec();
    let mut cache: Vec<i32> = vec![-1; n as usize];
    println!("{}", dp(0, &h_vec, &mut cache));
}
