    let mut a = input!(i64; n);
    let b = input!(i64; n);
    let mut c = input!(i64; n);

    a.sort();
    c.sort();

    let mut cnt: usize = 0;
    for x in b.iter() {
        cnt += a.lower_bound(x) * (c.len() - c.upper_bound(x));
