import math
input = sys.stdin.readline
MOD = 10**9 + 7

n, k = [int(item) for item in input().split()]
s = [int(item) for item in input().split()]
s.sort(reverse=True)
MAX_VAL = max(max(s), k)

dp = [[0] * (MAX_VAL + 1) for _ in range(n + 1)]
dp[0][k] = 1
for i, item in enumerate(s):
    for j in range(MAX_VAL + 1):
        if dp[i][j] == 0:
            continue
        # Apply item
        dp[i+1][j % item] += dp[i][j]
        dp[i+1][j % item] %= MOD
        # Put item afterwards
        dp[i+1][j] += dp[i][j] * (n - 1 - i)
        dp[i+1][j] %= MOD

ans = 0
for i, item in enumerate(dp[n]):
    ans += i * item
    ans %= MOD
print(ans)
