fn dfs(s: usize, n: usize, l: usize, es: &mut Vec<Vec<usize>>) {
    if n <= 1 {
        return;
    }
    let m = s + n / 2;
    for i in s..m {
        for j in m..s + n {
            es[i][j] = l;
        }
    }
    dfs(s, n / 2, l + 1, es);
    dfs(s + n / 2, (n + 1) / 2, l + 1, es);
}
