use std::fs;
use std::io::{stdin, Read};
struct UnionFind {
    parents: Vec<usize>,
}
impl UnionFind {
    pub fn new(n: usize) -> Self {
        let par = (0..n).collect();
        UnionFind { parents: par }
    }
    pub fn root(&mut self, x: usize) -> usize {
        if self.parents[x] == x {
            return x;
        }
        let par = self.parents[x];
        self.parents[x] = self.root(par);
        self.parents[x]
    }
    pub fn union(&mut self, x: usize, y: usize) {
        let rx = self.root(x);
        let ry = self.root(y);
        if rx == ry {
            return;
        }
        self.parents[rx] = ry;
    }
    pub fn is_same(&mut self, x: usize, y: usize) -> bool {
        let rx = self.root(x);
        let ry = self.root(y);
        rx == ry
    }
}

macro_rules! parse {
    ($it: ident) => {
        $it.next().unwrap().parse().unwrap()
    };
    ($it: ident,2) => {
        (parse!($it), parse!($it))
    };
    ($it: ident,3) => {
        (parse!($it), parse!($it), parse!($it))
    };
    ($it: ident,4) => {
        (parse!($it), parse!($it), parse!($it), parse!($it))
    };
    ($it: ident, $n: expr) => {
        (&mut $it).take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let (n, m) = parse!(it, 2);
    let x: Vec<usize> = parse!(it, n);
    let mut uf = UnionFind::new(n);
    let mut e: Vec<(usize, usize, usize)> = (0..m)
        .map(|_| {
            let (a, b, c): (usize, usize, usize) = parse!(it, 3);
            (a - 1, b - 1, c)
        })
        .collect::<Vec<_>>();
    e.sort_by_key(|&x| x.2);
    let mut weights = x.clone();
    let mut excludes = vec![0; n];
    for &(a, b, c) in e.iter() {
        let pa = uf.root(a);
        let pb = uf.root(b);
        if pa == pb {
            excludes[pa] += (weights[pa] < c) as usize
        } else {
            uf.union(pa, pb);
            let r = uf.root(pa);
            weights[r] = weights[pa] + weights[pb];
            excludes[r] = if weights[r] < c {
                excludes[pa] + excludes[pb] + 1
            } else {
                0
            };
        }
    }
    println!(
        "{}",
        (0..n)
            .filter(|&i| uf.root(i) == i)
            .map(|i| excludes[i])
            .sum::<usize>()
    );
