    dp[0][128] = 0;
    for i in 0..n {
        for j in 0..256 {
            if dp[i][j] == 1e18 as i64 { continue; } 
            for cc in c.iter() {
                let next = max(0, min(255, (j as i64 + *cc))) as usize;
                dp[i + 1][next] = min(dp[i + 1][next], dp[i][j] + (x[i] - next as i64).pow(2));
            }
        }
    }

    return *dp[n].iter().min().unwrap();
}

