    let mut gain = vec![0; 1 << n];
    for bits in 0 .. 1 << n {
        let mut sum = 0;
        for i in 0 .. n {
            if (bits & 1 << i) == 0 { continue; }
            for j in 0 .. i {
                if (bits & 1 << j) == 0 { continue; }
                sum += a[i][j];
