    let mut f: bool = true;

    for i in 0 .. n {
      if st[i] != '#' {
        if i < n - 1 && st[i+1] == '#' {st[i+1] = 'C'; f = false; break;}
        if i > 0 && st[i-1] == '#' {st[i-1] = 'C'; f = false; break;}
      }
    }
    if f {
      st[n/2] = 'C';
    }
  }
}

