  for i in 0 .. n {
    if st[i] != '#' {
      d[i] = 0;
      let mut j: usize = 1;
      while i >= j && st[i-j] == '#' && d[i-j] > j {
        d[i-j] = j;
        j += 1;
      }
      j = 1;
      while i+j < n && st[i+j] == '#' {
        d[i+j] = j;
        j += 1;
      }
    }
  }

  let mut md: usize = 0;
  let mut mi: usize = 0;

  for i in 0 .. n {
    if d[i] > md {
      md = d[i];
      mi = i;
    }
  }

  st[mi] = 'D';
}
