fn calc(k: i64, index: usize, seq: &Vec<i64>) -> bool {
    let n = seq.len();
    let mut dp = vec![false; k as usize];
    dp[0] = true;
    for i in 0..n {
        if i == index {
            continue;
        }
        for j in (0..k - seq[i]).rev() {
            let v = seq[i] + j;
            dp[v as usize] |= dp[j as usize];
        }
    }
    // println!("{} {:?}", index, dp);
    for i in 0..k {
        if i + seq[index] >= k && dp[i as usize] {
            return true;
        }
    }
    return false;
}

