    let mut dp = vec![vec![-1; v]; 1 << v];
    let ans = dfs((1 << v) - 1, 0, &mut dp, &g);
    println!("{}", if ans < INF {ans} else {-1});
}

fn dfs(b: usize, t: usize, dp: &mut Vec<Vec<i32>>, g: &Vec<Vec<i32>>) -> i32 {
    if dp[b][t] >= 0 { return dp[b][t]; }
    if b.count_ones() == 1 && g[0][t] >= 0 {return g[0][t]}
    let mut res = INF;
    let v = dp[0].len();
    for s in 0..v {
        if b & (1 << s) == 0 { continue; }
        if g[s][t] < 0 { continue; }
        let p = dfs(b ^ (1 << t), s, dp, g);
        if p == INF { continue; }
        res = min(res, p + g[s][t]);
    }
    dp[b][t] = res;
    res
}
