fn dfs(color: &mut Vec<Option<usize>>, target: usize, id: usize, g: &mut Vec<Vec<usize>>) {
    let mut s: VecDeque<usize> = VecDeque::new();
    s.push_back(target);
    color[target] = Some(id);

    while s.len() > 0 {
        let u: usize = s.pop_front().unwrap() as usize;
        for i in 0..g[u].len() {
            let v: usize = g[u][i];
            if color[v] == None {
                dfs(color, v, id, g);
            }
        }
    }
}

