fn main() {
    let n: usize = read();
    let s: Vec<char> = read::<String>().chars().collect();
    let q: usize = read();

    for _ in 0..q {
        let k: usize = read();
        let mut d: i64 = 0;
        let mut m: i64 = 0;
        let mut dm: i64 = 0;
        let mut ans: i64 = 0;
        for j in 0..n {
            match s[j] {
                'D' => d += 1,
                'M' => {
                    m += 1;
                    dm += d;
                }
                'C' => ans += dm,
                _ => {}
            }
            if j >= k - 1 {
                let l = j + 1 - k;
                match s[l] {
                    'D' => {
                        d -= 1;
                        dm -= m
                    }
                    'M' => m -= 1,
                    _ => {}
                }
            }
        }
        println!("{}", ans);
    }
}

