use std::cmp::max;
use std::collections::HashMap;
use std::error::Error;
use std::io;

pub fn main() {
    if let Err(_e) = run() {
        panic!("failed.");
    }
}

fn run() -> Result<(), Box<Error>> {
    let mut input = String::new();
    io::stdin().read_line(&mut input);
    let n = input.trim().parse::<i32>().unwrap();
    input.clear();
    let mut matrix = vec![];
    for _i in 0..n {
        io::stdin().read_line(&mut input);
        let row: Vec<i64> = input
            .trim()
            .split_whitespace()
            .map(|s| s.parse::<i64>().unwrap())
            .collect();
        matrix.push(row);
        input.clear();
    }

    let mut cache_sum: HashMap<i64, i64> = HashMap::new();
    cache_sum.insert(0, 0);

    let variations = 2.0f64.powi(n) as i32;
    for vairation in 1..variations {
        let mut new_one = vairation & -vairation;
        let previous_state = vairation - new_one;
        let mut new_one_index = 0;
        while new_one & 1 != 1 {
            new_one >>= 1;
            new_one_index += 1;
        }

        let mut sum = cache_sum.get(&(previous_state as i64)).unwrap().clone();
        for i in 0..n {
            if (previous_state >> i) & 1 == 1 {
                sum += matrix[i as usize][new_one_index as usize];
            }
        }
        cache_sum.insert(vairation as i64, sum);
    }

    //dp
    let mut dp = vec![0i64; variations as usize];
    let mut used = 0;
    while used < (1 << n) {
        let unused = used ^ ((1 << n) - 1);
        let mut use_ = unused;
        while use_ > 0 {
            if !(use_ > used) {
                use_ = (use_ - 1) & unused;
                continue;
            }
            dp[use_ | used] = max(
                dp[use_ | used],
                dp[used] + cache_sum.get(&(use_ as i64)).unwrap().clone(),
            );
            use_ = (use_ - 1) & unused;
        }
        used += 1;
    }
    println!("{}", dp[((1 << n) as usize - 1)]);
    Ok(())
}
