use std::cmp::min;
use std::io;
use std::io::prelude::*;
use std::iter::repeat;

struct MinSegTree {
    n: usize,
    nodes: Vec<i32>,
    lazy_nodes: Vec<Option<i32>>,
}

impl MinSegTree {
    fn new(n: usize) -> MinSegTree {
        let n = 1 << f64::log2(n as f64).ceil() as usize;
        MinSegTree {
            n,
            nodes: repeat(std::i32::MAX).take(2 * n - 1).collect(),
            lazy_nodes: repeat(None).take(2 * n - 1).collect(),
        }
    }

    fn update(&mut self, s: usize, t: usize, x: i32, ni: usize, l: usize, r: usize) {
        self.eval(ni);
        if r <= s || t <= l {
            return;
        }
        if s <= l && r <= t {
            self.lazy_nodes[ni] = Some(x);
            self.eval(ni);
            return;
        }
        let m = (l + r) / 2;
        self.update(s, t, x, 2 * ni + 1, l, m);
        self.update(s, t, x, 2 * ni + 2, m, r);
        self.nodes[ni] = min(self.nodes[2 * ni + 1], self.nodes[2 * ni + 2]);
    }

    fn eval(&mut self, ni: usize) -> i32 {
        match self.lazy_nodes[ni].take() {
            Some(x) => {
                self.nodes[ni] = x;
                if ni < self.n - 1 {
                    self.lazy_nodes[2 * ni + 1] = Some(x);
                    self.lazy_nodes[2 * ni + 2] = Some(x);
                }
            }
            None => {}
        }
        self.nodes[ni]
    }

    fn find(&mut self, s: usize, t: usize, ni: usize, l: usize, r: usize) -> i32 {
        self.eval(ni);
        if s <= l && r <= t {
            self.nodes[ni]
        } else if r <= s || t <= l {
            std::i32::MAX
        } else {
            let m = (l + r) / 2;
            min(
                self.find(s, t, 2 * ni + 1, l, m),
                self.find(s, t, 2 * ni + 2, m, r),
            )
        }
    }
}

