fn countryb(n: usize, st: &mut Vec<char>){
  if n == 1 { st[0] = 'B'; }
  else {
    let mut f: bool = true;

    for i in (0 .. n).rev() {
      if i == n - 1 {
        if st[i] == '#' && st[i-1] != 'A' {st[i] = 'B'; f = false; break;}
      }
      else if i == 0 {
        if st[i] == '#' && st[i+1] != 'A' {st[i] = 'B'; f = false; break;}
      }
      else {
        if st[i] == '#' && st[i+1] != 'A' && st[i-1] != 'A' {st[i] = 'B'; f = false; break;}
      }
    }
    if f {
