enum Status {
    Before,
    Active,
    Finished,
}

fn solve(graph: Vec<Vec<usize>>) {
    let size = graph.len();
    let mut status = vec![Status::Before; size];
    for i in 0..size {
        if Status::Finished == status[i] {
            continue;
        }
        let mut stack = vec![];
        stack.push(i);
        'outer: while !stack.is_empty() {
            let from = *stack.last().unwrap();
            if status[from] == Status::Before {
                // Preorder
                status[from] = Status::Active;
            }
            // For each child
            for &to in &graph[from] {
                match status[to] {
                    Status::Before => {
                        stack.push(to);
                        continue 'outer;
                    }
                    Status::Finished => {}
                    Status::Active => {
                        // A cycle detected.
                        println!("1");
                        return;
                    }
                }
            }
            // Postorder.
            let from = stack.pop().unwrap();
            status[from] = Status::Finished;
        }
    }
    println!("0");
}
