struct BIT {
    v: Vec<i64>,
}

impl BIT {
    fn new(n: usize) -> BIT {
        BIT { v: vec![0; n + 1] }
    }

    fn sum(&self, i: usize) -> i64 {
        if i == 0 {
            0
        } else {
            let ii = i as i64;
            self.v[i] + self.sum(i - (ii & (-ii)) as usize)
        }
    }

    fn add(&mut self, i: usize, x: i64) {
        if i < self.v.len() {
            self.v[i] += x;
            let ii = i as i64;
            self.add(i + (ii & (-ii)) as usize, x);
        }
    }
}

