fn modpow(x: i64, p: i64, m: i64) -> i64 {
    if p == 0 {
        1
    } else if p % 2 == 0 {
        modpow((x * x) % m, p / 2, m)
    } else {
        (x * modpow(x, p - 1, m)) % m 
    }
}
struct ModBinomial { m: i64, f: Vec<i64>, p: Vec<i64> }
impl ModBinomial {
    fn new(n: i64, m: i64) -> ModBinomial {
        let mut f = vec![1; n as usize + 1];
        let mut p = vec![1; f.len()];
        for i in 2..f.len() {
            f[i] = (i as i64 * f[i - 1]) % m;
            p[i] = modpow(f[i], m - 2, m);
        }
        ModBinomial { m: m, f: f, p: p }
    }
    fn bin(&self, n: i64, k: i64) -> i64 {
        (((self.f[n as usize] * self.p[k as usize])
            % self.m) * self.p[(n - k) as usize]) % self.m
    }
}


