struct Node {
    t: u64,
    c: usize,
    d: usize,
    n: Vec<(usize, usize, usize)>,
    s: Vec<u64>,
}

#[fastout]
fn main() {
    input! {
    in_n: u64, in_m: u64, in_s: usize,
    in_ns: [[usize; 4]; in_m], in_cs: [[usize; 2]; in_n]};
    let mut nodes = Vec::new();
    let size = (in_n * 50 + 1) as usize;

    for in_c in &in_cs {
        nodes.push(Node {
            t: M,
            c: in_c[0],
            d: in_c[1],
            n: vec![],
            s: vec![M; size],
        });
    }

    for in_n in &in_ns {
        nodes[in_n[0] - 1].n.push((in_n[1] - 1, in_n[2], in_n[3]));
        nodes[in_n[1] - 1].n.push((in_n[0] - 1, in_n[2], in_n[3]));
    }

    let mut queue = BinaryHeap::new();

    if in_s < size {
        queue.push((M, 0 as u64, 0, in_s));
    } else {
        queue.push((M, 0, 0, size - 1));
    }

    while !queue.is_empty() {
        let (_, t, i, s) = queue.pop().unwrap();

        if nodes[i].s[s] <= t {
            continue;
        }

        nodes[i].t = min(t, nodes[i].t);
        nodes[i].s[s] = t;

        if s + nodes[i].c < nodes[i].s.len() {
            let nt = t + nodes[i].d as u64;

            queue.push((M - nt, nt, i, s + nodes[i].c));
        }

        for n in &nodes[i].n {
            let (ni, rs, rt) = *n;
            let nt = t + rt as u64;

            if rs > s {
                continue;
            }

            queue.push((M - nt, nt, ni, s - rs));
        }
    }

    for n in nodes[1..].iter() {
        println!("{}", n.t);
    }
}
