fn calc(from: usize, parent: usize, g: &Graph, cnts: &Vec<usize>) -> (usize, usize, usize) {
    let mut ret = (cnts[from], 0, 0);
    for e in g[from].iter() {
        if e.dest == parent {
            continue;
