    let n: i64 = input();
    let m: i64 = input();
    let k: i64 = input();

    let mut xans = 0i64;
    for i in 1..m {
        xans += i * (m - i);
        xans %= MOD;
    }
    xans *= n * n;
    xans %= MOD;

    let mut yans = 0i64;
    for i in 1..n {
        yans += i * (n - i);
        yans %= MOD;
    }
    yans *= m * m;
    yans %= MOD;

    let comb = Combination::new(n * m);
    let mut ans = (xans + yans) % MOD;
    ans *= comb.combination(n * m - 2, k - 2);
    ans %= MOD;
    println!("{}", ans);
}

const MOD: i64 = 1000000007;

struct Combination {
    fact: Vec<i64>,
    ifact: Vec<i64>,
}

impl Combination {
    fn new(n: i64) -> Combination {
        let n = n as usize;
        let mut f = vec![0; n + 1];
        f[0] = 1;
        for i in 1..n + 1 {
            f[i] = f[i - 1] * i as i64 % MOD;
        }
        let mut invf = vec![0; n + 1];
        invf[n] = Combination::inverse(f[n]);
        for i in (1..n + 1).rev() {
            invf[i - 1] = invf[i] * i as i64 % MOD;
        }
        Combination {
            fact: f,
            ifact: invf,
        }
    }

    fn inverse(x: i64) -> i64 {
        Combination::power(x, MOD - 2)
    }

    fn power(x: i64, p: i64) -> i64 {
        if p == 0 {
            1
        } else if p % 2 == 0 {
            let t = Combination::power(x, p / 2);
            t * t % MOD
        } else {
            Combination::power(x, p - 1) * x % MOD
        }
    }

    fn combination(&self, n: i64, k: i64) -> i64 {
        if n < 0 || k < 0 || k > n {
            0
        } else {
            let (n, k) = (n as usize, k as usize);
            self.fact[n] * self.ifact[k] % MOD * self.ifact[n - k] % MOD
        }
    }
}
