use std::cmp::{max, min};

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    let t: i64 = sc.read();

    let mut zero = vec![];
    let mut ab = vec![];
    for _ in 0..n {
        let a: i64 = sc.read();
        let b: i64 = sc.read();
        if a == 0 {
            zero.push(b);
        } else {
            ab.push((a, b));
        }
    }
    zero.sort();
    let mut sum = vec![0; zero.len() + 1];
    for i in 0..zero.len() {
        sum[i + 1] = sum[i] + zero[i] + 1;
    }

    ab.sort_by(|&(a1, b1), &(a2, b2)| (a2 * (b1 + 1)).cmp(&(a1 * (b2 + 1))));

    let mut dp = vec![t + 1; 40];
    dp[0] = 0;
    for (a, b) in ab.into_iter() {
        for cur in (0..(dp.len() - 1)).rev() {
            let t0 = dp[cur] + 1;
            let wait = t0 * a + b;
            let next = t0 + wait;
            dp[cur + 1] = min(dp[cur + 1], next);
        }
    }

    let mut tail = zero.len();
    while sum[tail] > t {
        tail -= 1;
    }
    let mut ans = tail;
    for head in 0..dp.len() {
        let head_sum = dp[head];
        if head_sum > t {
            continue;
        }
        let remain = t - head_sum;
        let tail = sum
            .binary_search_by_key(&(2 * remain + 1), |&s| 2 * s)
            .err()
            .unwrap();
        ans = max(ans, head + tail - 1);
    }
    println!("{}", ans);
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        Self(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}
