fn solve(s: &Vec<char>, l: usize, r: usize, k: usize, mut dp: &mut Vec<Vec<Vec<i32>>>) -> i32 {
    if l > r {
        return 0
    }
    if dp[l][r][k] != -1 {
        return dp[l][r][k]
    }
    if l == r {
        dp[l][r][k] = 1;
        return 1
    }

    dp[l][r][k] = 0;
    if s[l] == s[r] {
        dp[l][r][k] = solve(&s, l + 1, r - 1, k, &mut dp) + 2;
    }
    if k + 1 < dp[0][0].len() {
        dp[l][r][k] = max(dp[l][r][k], solve(&s, l + 1, r - 1, k + 1, &mut dp) + 2);
    }
    dp[l][r][k] = max(dp[l][r][k], solve(&s, l + 1, r, k, &mut dp));
    dp[l][r][k] = max(dp[l][r][k], solve(&s, l, r - 1, k, &mut dp));

    dp[l][r][k]
}

