    let mut max_depth = 0;
    let mut max_vertex = cur;
    for &ci in g[cur].iter() {
        if ci == parent {
            continue;
        }
        let (depth, vertex) = dfs(g, ci, cur);
        if max_depth < depth {
            max_depth = depth;
            max_vertex = vertex;
        }
    }
    (1 + max_depth, max_vertex)
