    dp[0][0] = 1;
    for i in 0 .. n {
        // dp[i + 1] = ...
        for j in 0 .. c + 1 {
            for k in 0 .. j + 1 {
                dp[i + 1][j] += dp[i][k] * g(a[i], b[i], (j - k) as i64, &cache) % MOD;
                dp[i + 1][j] %= MOD;
            }
        }
    }
    return dp[n][c];
}

