fn solve(n: usize, vsc: &Vec<Vec<usize>>) -> i32 {
  let mut vst: Vec<u64> = (0 .. n).map(|i| 1 << i).collect();
  let gat: u64 = 2u64.pow(n as u32) - 1;

  let mut d: usize = 1;
  let ret: i32;

  loop {
    if d == 31 { ret = -1; break; }

    let mut t: u64 = 0;

    for s in &vsc[d] {
      t |= vst[*s];
    }

    for s in &vsc[d] {
      vst[*s] = t;
    }

    if (0..n).any(|i| vst[i] == gat) { ret = d as i32; break; }

    d += 1;
  }

  ret
}

